//! The fixtures of `app/open_file`, `app/nav_back`, `app/enter_edit`,
//! `app/files_open` and `app/files_expand` (docs/design/file_reader.md「性能」,
//! docs/design/bench.md「预算表」): git repositories in a temporary
//! directory, generated by the process target and removed with it. The big
//! files are untracked (the project hashes no tracked file of 64 MiB in the
//! background of the measurement); the rest is tracked.

use std::path::{Path, PathBuf};

use lectern_bench::{BenchError, Ctx};
use lectern_git::testing::TestRepo;
use lectern_project::testing::Shape;
use lectern_syntax::testing;

use crate::git_worktree::{self, module};

pub const MIB: usize = 1 << 20;

/// The old side of [`Changed`], a little under 4 MiB: `review` takes no
/// side above `MAX_VERSION_BYTES` (4 MiB) into a diff, and the generator
/// gives at least the length asked for.
pub const CHANGED_LEN: usize = 4 * MIB - (16 << 10);

/// The name of the scenario of 4 MiB of JavaScript in one line: recorded
/// on its own as `app/open_file/minified` (ADR 0065).
pub const MINIFIED: &str = "minified one line";

/// One file the reader opens: where, and at which byte (None: the start).
#[derive(Clone, Debug)]
pub struct Scenario {
    pub name: &'static str,
    pub path: PathBuf,
    pub byte: Option<u64>,
    /// The file's size.
    pub bytes: u64,
    /// A small file of the same language, opened (and closed) before the
    /// timed open: the first use of a language in a run compiles its
    /// highlight query, which the budget does not count (ADR 0064).
    pub warm: PathBuf,
}

/// The `cloudprint` shape with a few files of its own, in a worktree whose
/// root is canonical (`project` reports canonical roots, and the driver
/// finds a file by its path below the active tree's root).
pub struct ReaderRepo {
    repo: TestRepo,
    root: PathBuf,
}

impl ReaderRepo {
    /// The shape and two ordinary source files of about 300 lines,
    /// `src/module00.rs` and `src/module01.rs`.
    pub fn cloudprint() -> Result<ReaderRepo, BenchError> {
        ReaderRepo::of(git_worktree::shaped(&Shape::cloudprint()))
    }

    fn of(repo: TestRepo) -> Result<ReaderRepo, BenchError> {
        let root = repo
            .root()
            .canonicalize()
            .map_err(|e| BenchError::new(format!("the fixture's root: {e}")))?;
        let this = ReaderRepo { repo, root };
        this.write("src/module00.rs", &module(0, 0, false));
        this.write("src/module01.rs", &module(1, 0, false));
        // The small files that warm a language before a timed open.
        this.write("warm/warm.ts", &testing::ts(8 << 10, 1));
        this.write("warm/warm.js", &testing::minified_js(8 << 10, 1));
        this.write("warm/warm.json", &testing::json(8 << 10, 1));
        Ok(this)
    }

    pub fn root(&self) -> &Path {
        &self.root
    }

    fn write(&self, rel: &str, content: &[u8]) {
        self.repo.write_file(rel, content);
    }

    fn scenario(&self, name: &'static str, rel: &str, bytes: usize, byte: Option<u64>) -> Scenario {
        let warm = match Path::new(rel).extension().and_then(|e| e.to_str()) {
            Some("rs") => "src/module01.rs",
            Some("ts") => "warm/warm.ts",
            Some("js") => "warm/warm.js",
            Some("json") => "warm/warm.json",
            _ => panic!("no warm-up file for {rel}: add one of its language"),
        };
        Scenario {
            name,
            path: self.root.join(rel),
            byte,
            bytes: bytes as u64,
            warm: self.root.join(warm),
        }
    }

    /// An ordinary file of the shape's size, opened at its start.
    pub fn plain(&self) -> Scenario {
        let bytes = module(0, 0, false).len();
        self.scenario("plain", "src/module00.rs", bytes, None)
    }

    /// The two files `app/nav_back` goes between.
    pub fn pair(&self) -> (Scenario, Scenario) {
        let bytes = module(0, 0, false).len();
        (
            self.scenario("first", "src/module00.rs", bytes, None),
            self.scenario("second", "src/module01.rs", bytes, None),
        )
    }

    /// The scenarios of `app/open_file` that need no diff (ADR 0034): a 4 MiB
    /// and a 64 MiB synthetic TypeScript file opened at a byte offset in the
    /// middle, 4 MiB of JavaScript minified into one line opened at its start,
    /// and the middle of a 4 MiB `package-lock.json` (the byte offset of a
    /// hunk of its diff). 1 MiB, 2 MiB, 1 MiB and 1 MiB in a smoke run.
    pub fn large(&self, ctx: &Ctx) -> Vec<Scenario> {
        let small = ctx.scale(4 * MIB, MIB);
        let huge = ctx.scale(64 * MIB, 2 * MIB);
        let mut out = vec![self.plain()];
        let source = testing::ts(small, 0);
        self.write("big/source4.ts", &source);
        out.push(self.scenario(
            "4 MiB source",
            "big/source4.ts",
            source.len(),
            Some(source.len() as u64 / 2),
        ));
        drop(source);
        let source = testing::ts(huge, 0);
        self.write("big/source64.ts", &source);
        out.push(self.scenario(
            "64 MiB source",
            "big/source64.ts",
            source.len(),
            Some(source.len() as u64 / 2),
        ));
        drop(source);
        let minified = testing::minified_js(small, 0);
        self.write("big/app.min.js", &minified);
        out.push(self.scenario(MINIFIED, "big/app.min.js", minified.len(), None));
        drop(minified);
        let lock = testing::json(small, 0);
        self.write("big/package-lock.json", &lock);
        out.push(self.scenario(
            "lock file hunk",
            "big/package-lock.json",
            lock.len(),
            Some(lock.len() as u64 / 2),
        ));
        out
    }

    /// The file `app/enter_edit` enters the edit mode in: TypeScript at the
    /// edit limit (1 MiB, no line over 4 KiB; ADR 0034), a little under it.
    pub fn editable(&self) -> Scenario {
        let source = testing::ts(MIB - (16 << 10), 0);
        self.write("big/edit.ts", &source);
        self.scenario("edit limit", "big/edit.ts", source.len(), None)
    }
}

/// A git project whose worktree changes one line in the middle of a 4 MiB
/// TypeScript file (`src/old.ts`): the review of the changes outside any
/// session has one file, and the blob of the old side is what the reader
/// opens from it (ADR 0042).
pub struct Changed {
    /// The temporary directory goes with it.
    _repo: TestRepo,
    root: PathBuf,
    /// The offset of the changed line in the old blob.
    pub byte: u64,
    pub bytes: u64,
    /// The old blob's object ID, in hex.
    pub oid: String,
}

/// The tracked path of [`Changed`]'s file.
const CHANGED: &str = "src/old.ts";

impl Changed {
    pub fn new(len: usize) -> Result<Changed, BenchError> {
        let repo = TestRepo::new();
        let old = testing::ts(len, 0);
        let manifest = b"{ \"name\": \"fixture\" }\n".to_vec();
        let files: [(&str, &[u8]); 2] = [("package.json", &manifest), (CHANGED, &old)];
        for (path, content) in files {
            repo.write_file(path, content);
            repo.backdate(path);
        }
        let commit = repo.commit(repo.tree(&files), &[], "base");
        repo.set_ref("refs/heads/main", commit);
        let entries: Vec<_> = files.iter().map(|(path, _)| repo.add(path)).collect();
        repo.write_index(repo.common_dir(), &entries);
        // The change: one line of the middle, a class header with another
        // space in it, so its old side has a line to open.
        let needle: &[u8] = b"export class ";
        let from = old.len() / 2;
        let at = from
            + old[from..]
                .windows(needle.len())
                .position(|window| window == needle)
                .ok_or_else(|| BenchError::new("no class header in the middle of the file"))?;
        let mut new = old[..at].to_vec();
        new.extend_from_slice(b"export  class ");
        new.extend_from_slice(&old[at + needle.len()..]);
        repo.write_file(CHANGED, &new);
        let root = repo
            .root()
            .canonicalize()
            .map_err(|e| BenchError::new(format!("the fixture's root: {e}")))?;
        let oid = repo.blob(&old).to_hex();
        Ok(Changed {
            _repo: repo,
            root,
            byte: at as u64,
            bytes: old.len() as u64,
            oid,
        })
    }

    pub fn root(&self) -> &Path {
        &self.root
    }

    /// The changed file.
    pub fn path(&self) -> PathBuf {
        self.root.join(CHANGED)
    }
}

/// The large repository of `app/files_open` and `app/files_expand`
/// (`app/idle_100k`'s shape: 100 000 files and 2 000 manifests; 2 000 files
/// in a smoke run) with a directory of 2 000 files that comes first in the
/// tree, so the first row of the Files tree is the directory to open
/// (2 000 children; 50 in a smoke run).
pub struct Wide {
    /// The temporary directory goes with it.
    _repo: TestRepo,
    root: PathBuf,
    /// How many files the wide directory holds.
    pub children: usize,
    pub files: usize,
}

impl Wide {
    pub fn new(ctx: &Ctx) -> Result<Wide, BenchError> {
        let (files, manifests) = ctx.scale((100_000, 2_000), (2_000, 40));
        let children = ctx.scale(2_000, 50);
        let mut shape = Shape::monorepo(files, manifests);
        shape
            .paths
            .extend((0..children).map(|i| format!("aaa-wide/f{i:04}.txt")));
        shape.paths.sort();
        shape.paths.dedup();
        let repo = git_worktree::shaped(&shape);
        let root = repo
            .root()
            .canonicalize()
            .map_err(|e| BenchError::new(format!("the fixture's root: {e}")))?;
        Ok(Wide {
            _repo: repo,
            root,
            children,
            files: shape.paths.len(),
        })
    }

    pub fn root(&self) -> &Path {
        &self.root
    }
}
